            match path{[]=>Ok(V::Record(&[1,2])),[0]=>Ok(V::Bytes(&self.bytes)),[1]=>Ok(V::Text(&self.text)),_=>Err(semio_framework_dsl_record::native_encoding::projection_path_error())}
